{
  "probability": 0.81,
  "range_low": 0.72,
  "range_high": 0.90,
  "summary": [
    "Pre-election polls show CDU ahead or narrowly ahead of Greens, supporting CDU as the largest party.",
    "Greens have been closing the gap in several polls, creating downside risk to a CDU lead.",
    "AfD holds a sizable share, introducing vote fragmentation that can affect seat allocation.",
    "Historical pattern shows Greens winning most seats in BW in 2016 and 2021, injecting uncertainty into CDU's edge."
  ],
  "confidence": "high",
  "narrative": "Bayesian updates from credible polls push CDU toward the largest-seat outcome, with an 81% posterior. While Greens closing the gap and turnout/coalition uncertainties temper the edge, the calibrated probability remains high for CDU to win the most seats.",
  "justification": {
    "anchor": {
      "probability": 0.60,
      "basis": "reference class of BW Landtag elections with credible polling indicating CDU leads or is close, and seat projections frequently favor CDU in the current cycle"
    },
    "factor_updates": [
      {
        "factor": "Persistent CDU lead persists",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "CDU leads in multiple credible polls and seat projections, lifting the posterior probability above the anchor."
      },
      {
        "factor": "Greens closing the gap",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Greens narrowing the gap in late-February polls reduces CDU's clear edge, tempering the probability."
      },
      {
        "factor": "AfD vote share remains sizable",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Significant AfD support fragments votes and can alter seat distribution, reducing CDU's relative majority."
      },
      {
        "factor": "Historical base-rate: Greens won in 2016 and 2021",
        "direction": "down",
        "magnitude": "weak",
        "rationale": "Past performance suggests the base-rate is not strongly in CDU's favor, introducing downside risk to a simple CDU majority."
      },
      {
        "factor": "Turnout and coalition dynamics inject uncertainty",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "Turnout swings and feasible coalitions can shift seat counts even with a vote lead."
      }
    ],
    "synthesis_rationale": "Combining a credible CDU lead signal with countervailing pressures (Greens gains, AfD fragmentation, turnout effects) yields a higher posterior than the anchor, but not certainty. Calibration treats poll-based inputs as probabilistic signals with moderate-to-weak effects where uncertainty remains, arriving at 0.81 with a wide but plausible range (0.72–0.90)."
  }
}

{
  "probability": 0.81,
  "range_low": 0.72,
  "range_high": 0.90,
  "summary": [
    "Pre-election polls show CDU leading or closely trailing Greens, with seat projections favoring CDU (e.g., CDU ~36 seats vs Greens ~28).",
    "Greens have shown occasional momentum in some polls, and AfD remains a sizable fragment (around 19–20%), adding uncertainty to seat allocation.",
    "Historically Greens led in 2016 and 2021; CDU led only in 2011, so the base rate is modest for CDU winning the most seats.",
    "A Bayesian update yields a posterior probability of 0.81 that CDU will win the most seats, reflecting current signals and remaining uncertainties."
  ],
  "confidence": "high",
  "narrative": "Current polls suggest a CDU majority of seats is likely but not guaranteed, with Greens pressuring the lead and AfD fragmentation creating variance. The posterior of 0.81 reflects a strong but not absolute confidence given turnout and coalition dynamics.",
  "justification": {
    "anchor": {
      "probability": 0.33,
      "basis": "Base-rate anchor from BW history: CDU was the largest 2011; Greens were largest in 2016 and 2021; thus a modest prior probability (~1/3) that CDU would win the most seats in 2026."
    },
    "factor_updates": [
      {
        "factor": "Persistent CDU polling lead",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Multiple credible polls show CDU ahead or narrowly ahead Greens, supporting a higher probability than the base-rate anchor."
      },
      {
        "factor": "Greens closing the gap in polls",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Several polls show Greens narrowing CDU's lead, which lowers the CDU advantage and reduces the likelihood of CDU taking most seats."
      },
      {
        "factor": "AfD vote share remains sizable",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "If AfD siphons votes, CDU's seat share could be affected; fragmentation reduces a clean CDU majority of seats."
      },
      {
        "factor": "Turnout and coalition dynamics",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "Uncertain turnout and coalition possibilities can alter seat distribution, adding uncertainty to the translate-from-vote to seats step."
      },
      {
        "factor": "Electoral-system nuances / 2026 rules",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Any changes affect seat allocation mechanics and can dampen or amplify the effect of a vote lead on seats."
      }
    ],
    "synthesis_rationale": "The posterior is computed by starting from a modest base-rate anchor (33%), applying moderate upward pressure from persistent CDU leads, while incorporating downward adjustments for Greens gains, AfD fragmentation, and rule-induced allocation uncertainty. The net effect yields a high-confidence posterior of 0.81, with a plausible range reflecting turnout and district-level variability."
  }
}

