  "range_low": 0.25,
  "range_high": 0.40,
  "summary": [
    "CDU leads in polls but Greens have closed the gap in several surveys, keeping the outcome uncertain.",
    "Historical pattern in BW shows Greens winning the most seats in 2016 and 2021, which tempers any CDU advantage.",
    "Pre-election signals suggest a narrow path for CDU to win the most seats, with turnout and coalition math driving substantial uncertainty."
  ],
  "confidence": "medium",
  "narrative": "Pre-election polling signals a CDU lead, but Greens closing the gap and the Green coalition risk keep the race tight. Given the reference-class anchor around a 1-in-3 baseline for CDU to win the most seats, the current signals imply a calibrated probability near 31%, with a wide uncertainty range due to turnout and coalition dynamics.",
  "justification": {
    "anchor": {
      "probability": 0.33,
      "basis": "reference_class: Baden-Württemberg Landtag elections since 2011; Greens have been largest party in 2016 and 2021, CDU in 2011. The long-term base rate for CDU winning the most seats is about one-third."
    },
    "factor_updates": [
      {
        "factor": "CDU polling lead persists ahead of Greens",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Multiple credible polls show CDU in the high-20s while Greens cluster in the mid-20s, supporting a probability shift toward CDU winning the most seats."
      },
      {
        "factor": "Greens closing the gap in late-February polls",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Polls show Greens narrowing the gap or surpassing CDU in some polls, offsetting CDU's edge and reducing probability of CDU securing the most seats."
      },
      {
        "factor": "AfD vote share remains sizable (~19-20%)",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Fragmentation reduces CDU's direct path to a clear lead in seats."
      },
      {
        "factor": "Historical base-rate: Greens won BW in 2016 and 2021",
        "direction": "down",
        "magnitude": "weak",
        "rationale": "Historically not a CDU stronghold; this reduces the base probability of CDU winning most seats relative to Greens."
      },
      {
        "factor": "Turnout and coalition dynamics inject uncertainty",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "Coalition options and turnout swings can alter seat allocation, adding uncertainty."
      }
    ],
    "synthesis_rationale": "Starting from a ~0.33 anchor due to the reference class, we applied modest positive updates for CDU lead signals and larger negative updates for Greens narrowing the gap and for vote fragmentation. The net effect is a downward tilt from the anchor, yielding a calibrated probability near 0.31 with a broad uncertainty range to reflect turnout and coalition unpredictability."
  }
}
